// Finds modules, dashboard screens and migrations, and writes the generated files the app imports.
// Run by `npm run dev`, `npm run typecheck`, `npm test` and the end-to-end server. Safe to run any time.
//
//   src/modules/<id>/module.ts          -> src/generated/modules.ts
//   src/dashboard/<name>/index.tsx      -> src/generated/screens.ts
//   src/core/migrations/*.sql           -> migrations/core_<file>
//   src/modules/<id>/migrations/*.sql   -> migrations/m_<id>_<file>
//
// Wrangler applies migrations in file-name order, so core tables always exist before module tables.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'src');

function dirs(path) {
  if (!existsSync(path)) return [];
  return readdirSync(path, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
    .sort();
}

function sqlFiles(path) {
  if (!existsSync(path)) return [];
  return readdirSync(path)
    .filter((f) => f.endsWith('.sql'))
    .sort();
}

function writeIfChanged(path, content) {
  if (existsSync(path) && readFileSync(path, 'utf8') === content) return;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
}

const header = '// Generated by scripts/prepare.mjs. Do not edit.\n';

// Modules
const moduleIds = dirs(join(src, 'modules')).filter((id) => existsSync(join(src, 'modules', id, 'module.ts')));
for (const id of moduleIds) {
  if (!/^[a-z][a-z0-9-]{1,30}$/.test(id)) throw new Error(`Bad module folder name: src/modules/${id}`);
}
writeIfChanged(
  join(src, 'generated', 'modules.ts'),
  header +
    "import type { ModuleDef } from '../core/module';\n" +
    moduleIds.map((id, i) => `import m${i} from '../modules/${id}/module';\n`).join('') +
    `\nexport const modules: ModuleDef[] = [${moduleIds.map((_, i) => `m${i}`).join(', ')}];\n`,
);

// Dashboard screens
const screenNames = dirs(join(src, 'dashboard')).filter((name) => existsSync(join(src, 'dashboard', name, 'index.tsx')));
writeIfChanged(
  join(src, 'generated', 'screens.ts'),
  header +
    "import type { Hono } from 'hono';\n" +
    "import type { AppEnv } from '../env';\n" +
    screenNames.map((name, i) => `import s${i} from '../dashboard/${name}/index';\n`).join('') +
    `\nexport const screens: Record<string, Hono<AppEnv>> = {${screenNames.map((name, i) => ` '${name}': s${i}`).join(',')} };\n`,
);

// Migrations
const out = join(root, 'migrations');
const wanted = new Map();
for (const f of sqlFiles(join(src, 'core', 'migrations'))) wanted.set(`core_${f}`, join(src, 'core', 'migrations', f));
for (const id of moduleIds) {
  const dir = join(src, 'modules', id, 'migrations');
  for (const f of sqlFiles(dir)) wanted.set(`m_${id.replace(/-/g, '_')}_${f}`, join(dir, f));
}
mkdirSync(out, { recursive: true });
for (const f of readdirSync(out)) if (!wanted.has(f)) rmSync(join(out, f));
for (const [name, from] of wanted) writeIfChanged(join(out, name), readFileSync(from, 'utf8'));

console.log(`prepare: ${moduleIds.length} modules, ${screenNames.length} screens, ${wanted.size} migrations`);
